macro_rules! deps {
    () => {
        MatchKind!();
        Match!();
        PrefilterI!();
    };
}

macro_rules! Prefilter {
    () => {
        deps!();
        # [doc = " A prefilter for accelerating regex searches."] # [doc = ""] # [doc = " If you already have your literals that you want to search with,"] # [doc = " then the vanilla [`Prefilter::new`] constructor is for you. But"] # [doc = " if you have an [`Hir`] value from the `regex-syntax` crate, then"] # [doc = " [`Prefilter::from_hir_prefix`] might be more convenient. Namely, it uses"] # [doc = " the [`regex-syntax::hir::literal`](regex_syntax::hir::literal) module to"] # [doc = " extract literal prefixes for you, optimize them and then select and build a"] # [doc = " prefilter matcher."] # [doc = ""] # [doc = " A prefilter must have **zero false negatives**. However, by its very"] # [doc = " nature, it may produce false positives. That is, a prefilter will never"] # [doc = " skip over a position in the haystack that corresponds to a match of the"] # [doc = " original regex pattern, but it *may* produce a match for a position"] # [doc = " in the haystack that does *not* correspond to a match of the original"] # [doc = " regex pattern. If you use either the [`Prefilter::from_hir_prefix`] or"] # [doc = " [`Prefilter::from_hirs_prefix`] constructors, then this guarantee is"] # [doc = " upheld for you automatically. This guarantee is not preserved if you use"] # [doc = " [`Prefilter::new`] though, since it is up to the caller to provide correct"] # [doc = " literal strings with respect to the original regex pattern."] # [doc = ""] # [doc = " # Cloning"] # [doc = ""] # [doc = " It is an API guarantee that cloning a prefilter is cheap. That is, cloning"] # [doc = " it will not duplicate whatever heap memory is used to represent the"] # [doc = " underlying matcher."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " This example shows how to attach a `Prefilter` to the"] # [doc = " [`PikeVM`](crate::nfa::thompson::pikevm::PikeVM) in order to accelerate"] # [doc = " searches."] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::{"] # [doc = "     nfa::thompson::pikevm::PikeVM,"] # [doc = "     util::prefilter::Prefilter,"] # [doc = "     Match, MatchKind,"] # [doc = " };"] # [doc = ""] # [doc = " let pre = Prefilter::new(MatchKind::LeftmostFirst, &[\"Bruce \"])"] # [doc = "     .expect(\"a prefilter\");"] # [doc = " let re = PikeVM::builder()"] # [doc = "     .configure(PikeVM::config().prefilter(Some(pre)))"] # [doc = "     .build(r\"Bruce \\w+\")?;"] # [doc = " let mut cache = re.create_cache();"] # [doc = " assert_eq!("] # [doc = "     Some(Match::must(0, 6..23)),"] # [doc = "     re.find(&mut cache, \"Hello Bruce Springsteen!\"),"] # [doc = " );"] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [doc = ""] # [doc = " But note that if you get your prefilter incorrect, it could lead to an"] # [doc = " incorrect result!"] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::{"] # [doc = "     nfa::thompson::pikevm::PikeVM,"] # [doc = "     util::prefilter::Prefilter,"] # [doc = "     Match, MatchKind,"] # [doc = " };"] # [doc = ""] # [doc = " // This prefilter is wrong!"] # [doc = " let pre = Prefilter::new(MatchKind::LeftmostFirst, &[\"Patti \"])"] # [doc = "     .expect(\"a prefilter\");"] # [doc = " let re = PikeVM::builder()"] # [doc = "     .configure(PikeVM::config().prefilter(Some(pre)))"] # [doc = "     .build(r\"Bruce \\w+\")?;"] # [doc = " let mut cache = re.create_cache();"] # [doc = " // We find no match even though the regex does match."] # [doc = " assert_eq!("] # [doc = "     None,"] # [doc = "     re.find(&mut cache, \"Hello Bruce Springsteen!\"),"] # [doc = " );"] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [derive (Clone , Debug)] pub struct Prefilter { # [cfg (not (feature = "alloc"))] _unused : () , # [cfg (feature = "alloc")] pre : Arc < dyn PrefilterI > , # [cfg (feature = "alloc")] is_fast : bool , # [cfg (feature = "alloc")] max_needle_len : usize , }
    };
}

Prefilter!()